        h2: "Чи дає шлюб право на проживання",
        html: `<p>Коротка відповідь: <b>не автоматично</b>, але шлюб є підставою для окремої процедури.</p>
<p>Шлюб із громадянином України сам по собі не надає ні права на проживання, ні громадянства. Він є підставою для звернення за <b>посвідкою на тимчасове проживання</b> як член сім'ї громадянина України — це окрема процедура зі своїм пакетом документів і строками. Порядок описаний у матеріалі про <a href="/blog/yak-otrymaty-posvidku-na-prozhyvannya/">посвідку на проживання</a>.</p>
<p>Щодо громадянства: шлюб із громадянином України не дає його автоматично. Він впливає на умови прийняття до громадянства, зокрема на вимогу щодо строку проживання, але процедура залишається окремою й тривалою. Детально — у матеріалі про <a href="/blog/gromadyanstvo-za-shlyubom-z-gromadyaninom/">громадянство за шлюбом</a>.</p>
<p><b>Про шлюбний договір.</b> Це інструмент, який у шлюбі з іноземним елементом має більше сенсу, ніж у звичайному. Причина проста: подружжя з різних країн із більшою ймовірністю матиме майно в кількох юрисдикціях і з більшою ймовірністю зіткнеться з питанням, право якої держави застосовувати. Шлюбний договір дозволяє врегулювати режим майна заздалегідь, і укласти його з іноземцем можна як до реєстрації шлюбу, так і під час нього. Деталі — у матеріалі про <a href="/blog/shlyubnyy-dohovir/">шлюбний договір</a>.</p>
<p>І на випадок, якщо шлюб доведеться розривати: порядок із іноземним елементом має власні правила підсудності — див. матеріал про <a href="/blog/rozluchennya-z-inozemtsem/">розлучення з іноземцем</a>.</p>
<p>Юристи практики <a href="/practices/family-law/">сімейного права LEGIUS</a> супроводжують реєстрацію шлюбу з іноземним елементом — від перевірки документів і легалізації до шлюбного договору.</p>`,
