        h2: "Спадкування після розлучення",
        html: `<p>Тут відповідь коротка й однозначна: <b>колишнє подружжя не спадкує за законом.</b> Право на спадкування в першу чергу має лише той із подружжя, <b>хто пережив спадкодавця і перебував з ним у шлюбі</b> на момент смерті. Розірвання шлюбу це право припиняє повністю.</p>
<p>Три супутні ситуації, які варто розрізняти.</p>
<ul>
<li><b>Шлюб розірвано, майно не поділено.</b> Право на спадкування зникає, а право на поділ спільного майна — ні. Дружина і чоловік мають право на поділ майна, що належить їм на праві спільної сумісної власності, <b>незалежно від розірвання шлюбу</b> (ст. 69 СК). Тобто колишня дружина не спадкує, але може вимагати свою частку в спільно набутому майні — і ця вимога пред'являється до спадкоємців.</li>
<li><b>Заповіт на користь колишнього подружжя.</b> Діє. Заповіт можна скласти на будь-кого, і родинний чи шлюбний зв'язок для цього не потрібен. Якщо заповіт не скасовано після розлучення, колишній партнер успадкує за ним.</li>
<li><b>Фактичне роздільне проживання без розлучення.</b> Шлюб не розірвано, тому право на спадкування в першу чергу зберігається — навіть якщо подружжя роками не живе разом. Виняток становить встановлений судом режим окремого проживання, але й він шлюбу не припиняє: див. матеріал про <a href="/blog/rozirvannya-shlyubu/">розірвання шлюбу</a>.</li>
</ul>
<p><b>Чи можна позбавити подружжя спадщини.</b> Так — заповітом на користь інших осіб. Але з двома застереженнями: обов'язкова частка непрацездатної вдови або вдівця зберігається незалежно від змісту заповіту, і частка у спільному майні взагалі не є спадщиною, тому заповітом її передати неможливо. Отже, «позбавити всього» заповітом не вийде: майно, набуте в шлюбі, наполовину належить другому з подружжя за законом.</p>
<p>Юристи практики <a href="/practices/family-law/">сімейного права LEGIUS</a> розраховують частки у спадщині з урахуванням подружньої частки та обов'язкової частки, супроводжують оформлення спадщини й спори між спадкоємцями.</p>`,
