        h2: "Терміновий заборонний припис: перший і найшвидший крок",
        html: `<p>Це інструмент негайного реагування. <b>Хто виносить:</b> уповноважені підрозділи органів Національної поліції України. <b>Підстава:</b> існування <b>безпосередньої загрози життю чи здоров'ю</b> постраждалої особи — з метою негайного припинення насильства, недопущення його продовження чи повторного вчинення.</p>
<p><b>За чиєю заявою:</b> за заявою постраждалої особи <b>або за власною ініціативою</b> працівника поліції — за результатами <b>оцінки ризиків</b>. Оцінка ризиків проводиться за затвердженою методикою, і саме її результат формально обґрунтовує припис.</p>
<p><b>Строк: до 10 діб.</b> Це не продовжується — за цей час потрібно перейти до обмежувального припису через суд.</p>
<p><b>Які заходи може містити:</b></p>
<ul>
<li>зобов'язання <b>залишити місце проживання (перебування)</b> постраждалої особи;</li>
<li>заборона на вхід та перебування в місці проживання постраждалої особи;</li>
<li>заборона <b>в будь-який спосіб контактувати</b> з постраждалою особою.</li>
</ul>
<p>Два важливі застереження. По-перше, <b>зобов'язання залишити житло й заборона контактувати не застосовуються, якщо кривдником є особа віком до 18 років</b>. По-друге — і це те, чого багато хто не знає, — <b>кривдник не може «відмовитися» виселятися</b>: якщо він не залишає житло добровільно, поліція має повноваження забезпечити виконання припису.</p>
<p>Кривдник, якому приписом визначено залишити місце спільного проживання, <b>зобов'язаний повідомити поліцію про місце свого тимчасового перебування</b> у встановлений законом строк. Невиконання цього обов'язку — окреме адміністративне правопорушення.</p>
<p><b>Важливо про право власності.</b> Терміновий заборонний припис про виселення <b>не залежить від того, кому належить житло</b>. Кривдника можна зобов'язати залишити квартиру, яка є його власністю, якщо в ній проживає постраждала особа. Припис не позбавляє права власності — він тимчасово обмежує право користування. Це найчастіше питання, яке ставлять у таких справах, і відповідь на нього саме така.</p>`,
