        html: `<ol>
<li><b>102</b> — поліція, у гострій ситуації. Вимагайте оцінки ризиків і термінового заборонного припису; наполягайте на реєстрації заяви та отриманні її номера.</li>
<li><b>1547</b> — урядова гаряча лінія з питань протидії домашньому насильству, торгівлі людьми та дискримінації за ознакою статі. Працює круглодобово, консультує і спрямовує.</li>
<li><b>Служба у справах дітей</b> — якщо постраждала дитина або дитина була свідком. Орган опіки та піклування може самостійно подати до суду заяву про обмежувальний припис.</li>
<li><b>Медичний заклад</b> — зафіксуйте ушкодження або стан здоров'я навіть за відсутності видимих слідів. Медичний документ стає доказом і в адміністративній, і в кримінальній справі.</li>
<li><b>Суд</b> — заява про обмежувальний припис. За п. 12-1 ч. 2 ст. 3 Закону «Про судовий збір» судовий збір за подання такої заяви <b>не справляється</b>.</li>
<li><b>Безоплатна правнича допомога</b> — особи, які постраждали від домашнього насильства або насильства за ознакою статі, мають право на безоплатну <b>вторинну</b> правничу допомогу: представництво в судах та інших органах і складення процесуальних документів із питань, пов'язаних із захистом їхніх прав. Це право <b>не залежить від рівня доходу</b>.</li>
</ol>
<p>Що варто робити паралельно:</p>
<ul>
<li>зберігати <b>копії</b>, а не оригінали документів, і тримати їх окремо від спільного житла;</li>
<li>вести хронологію епізодів із датами — на цьому тримається доказування систематичності;</li>
<li>не видаляти переписку, навіть неприємну; скриншот без збереженого чату має меншу вагу;</li>
<li>подумати про <a href="/blog/viznachennya-mistsya-prozhyvannya-dytyny/">визначення місця проживання дитини</a> і, за наявності підстав, про <a href="/blog/pozbavlennya-batkivskykh-prav/">позбавлення батьківських прав</a> — приписи дають безпеку, але не вирішують питання дитини назавжди;</li>
<li>якщо йдеться й про розлучення — порядок описано в матеріалі про <a href="/blog/rozirvannya-shlyubu/">розірвання шлюбу</a>. Окремо варто знати: за ч. 2 ст. 110 СК позов про розірвання шлюбу не може бути поданий під час вагітності дружини та протягом року після народження дитини — але <b>це обмеження не діє</b>, якщо один із подружжя вчинив протиправну поведінку з ознаками кримінального правопорушення щодо другого з подружжя або щодо дитини.</li>
</ul>`,
