<p><b>Строк і відкликання.</b> Розірвання шлюбу триває <b>місяць з дня подання заяви</b> — це загальне правило, і онлайн-формат його не скорочує. Протягом цього часу заяву можна відкликати, але <b>не пізніше ніж за 4 години</b> до відеоконференції.</p>
