<p>Окремий варіант для подружжя з дітьми, який пришвидшує справу: <b>спільна заява про розірвання шлюбу</b> разом із письмовою угодою про те, з ким проживатимуть діти, як відбуватиметься їх утримання та участь у вихованні. Договір про аліменти при цьому має бути <b>нотаріально посвідчений</b>. Суд ухвалює рішення після перевірки, чи не порушуються права дітей і подружжя, і <b>не раніше ніж через місяць</b> після подання заяви.</p>
