        id: "s4",
        h2: "Які є обмеження",
        html: `<p><b>Чого онлайн не буває:</b></p>
<ul>
<li><b>розлучення через «Дію» за наявності спільних неповнолітніх дітей</b> — ця вимога безумовна;</li>
<li><b>розлучення без згоди другого з подружжя</b> — у «Дії» заяву не вдасться навіть сформувати;</li>
<li><b>розлучення, якщо хтось із подружжя не є громадянином України</b>, — онлайн-послуга в «Дії» для цього не передбачена;</li>
<li><b>вирішення майнових спорів і спорів про дітей</b> — це окремі провадження, і розірвання шлюбу їх не охоплює. Майнові спори, до речі, <b>не впливають на сам факт розлучення</b>: шлюб можна розірвати, не чекаючи на поділ майна.</li>
</ul>
<p><b>Який документ ви отримаєте</b> — залежить від шляху, і це важливо для подальших процедур:</p>
<table>
<thead><tr><th>Шлях</th><th>Документ</th></tr></thead>
<tbody>
<tr><td>ДРАЦС (у т. ч. через «Дію»)</td><td><b>свідоцтво про розірвання шлюбу</b></td></tr>
<tr><td>Суд</td><td><b>рішення суду</b>, що набрало законної сили — свідоцтво не видається</td></tr>
</tbody>
</table>
<p>За статтею 115 СК рішення суду після набрання законної сили <b>надсилається судом до органу ДРАЦС</b> за місцем його ухвалення. Відомості вносяться до Державного реєстру актів цивільного стану, а в актовому записі про шлюб проставляється відмітка про розірвання. Окремо звертатися до ДРАЦС після суду не потрібно.</p>
<p>Перевірити результат можна самостійно: у застосунку «Дія» відмітка про розірвання шлюбу відображається в актовому записі про шлюб у розділі «Повна інформація». А витяг з Державного реєстру актів цивільного стану — зокрема для підтвердження дошлюбного прізвища — можна отримати в будь-якому відділі ДРАЦС незалежно від місця проживання чи місця складання актового запису.</p>
<p>Юристи практики <a href="/practices/family-law/">сімейного права LEGIUS</a> супроводжують розлучення дистанційно — від вибору шляху до отримання документів, включно зі справами, де є діти або майновий спір. Суміжні питання — у матеріалі про <a href="/blog/alimenty-na-dytynu/">аліменти на дитину</a>.</p>`,
