<li>в <b>усіх інших спорах</b> між батьками — про визначення місця проживання дитини, про порядок участі у спілкуванні та вихованні, про аліменти — забезпечення позову шляхом обмеження права на виїзд за межі України <b>не є можливим</b>.</li>
