        h2: "Правові наслідки, недійсність і скасування",
        html: `<p>З моменту усиновлення (ст. 232 СК):</p>
<ul>
<li><b>припиняються</b> особисті та майнові права й обов'язки між дитиною та її батьками, а також між нею та іншими родичами за походженням — із винятками, описаними вище;</li>
<li><b>виникають</b> взаємні особисті немайнові та майнові права й обов'язки між усиновленою особою (а в майбутньому — її дітьми та внуками) і усиновлювачем та його родичами за походженням;</li>
<li>усиновлювач отримує права й обов'язки щодо дитини <b>в тому самому обсязі</b>, який мають батьки;</li>
<li>усиновлена особа отримує права й обов'язки щодо усиновлювача <b>в тому самому обсязі</b>, який має дитина щодо своїх батьків.</li>
</ul>
<p>Практично це означає повний обсяг: право на утримання й аліменти, спадкування за законом у першій черзі, право на пільги, представництво, обов'язок піклуватися про усиновлювача в майбутньому. Питання черг і часток докладно розібране в матеріалі про <a href="/blog/spadkuvannya-podruzhzhyam/">спадкування подружжям</a>.</p>
<h3>Недійсність і скасування</h3>
<p>Закон розрізняє дві різні конструкції.</p>
<p><b>Недійсність усиновлення</b> (ст. 236 СК) — коли воно було здійснене з порушенням закону: за підробленими документами, без згоди, яка була потрібна, фіктивно (без мети створення сім'ї). Визнання усиновлення недійсним <b>припиняє права та обов'язки</b>, які виникли раніше й були встановлені законом для усиновлювача, і <b>відновлює</b> права та обов'язки між дитиною та її батьками й родичами за походженням.</p>
<p><b>Скасування усиновлення</b> (ст. 238 СК) — коли усиновлення відбулося законно, але згодом виявилося, що воно суперечить інтересам дитини, не забезпечує їй сімейного виховання, або дитина страждає на недоумство чи психічну хворобу, про яку усиновлювач не знав. Скасування можливе лише за рішенням суду і, як правило, не допускається після досягнення дитиною повноліття — крім випадків, передбачених законом.</p>
<p>Окремо усиновлювач може бути <b>позбавлений батьківських прав</b> на тих самих підставах, що й батьки (ст. 242 СК).</p>
<h3>Державна підтримка</h3>
<p>З 1 січня 2026 року систему допомог сім'ям з дітьми перебудували: більшість виплат призначає й виплачує <b>Пенсійний фонд України</b>, а конкретні розміри щороку визначаються законом про Державний бюджет. Через це наводити суму тут було б не на користь читачеві: актуальний розмір виплат для усиновлювачів потрібно звіряти в ПФУ <b>на дату звернення</b>. Що залишилося незмінним — право подати заяву й окремий порядок для кожного виду допомоги: автоматично нічого не призначається.</p>`,
