        h2: "Що закон розуміє під цивільним шлюбом",
        html: `<p>Терміна «цивільний шлюб» у законі немає. Є інститут <b>проживання однією сім'єю без реєстрації шлюбу</b>, і головне правило щодо нього сформульоване коротко: <b>проживання однією сім'єю не є підставою для виникнення у жінки та чоловіка прав та обов'язків подружжя</b>. Релігійний обряд шлюбу — також не є.</p>
<p>Що натомість є: частина друга статті 3 СК визначає, що <b>сім'ю складають особи, які спільно проживають, пов'язані спільним побутом, мають взаємні права та обов'язки</b>. Із цього визначення і з практики виростають усі наслідки.</p>
<p>Конституційний Суд у рішенні від 03.06.1999 № 5-рп/99 (п. 6) назвав обов'язкові умови визнання осіб членами однієї сім'ї: спільне проживання, ведення спільного господарства, наявність спільних витрат, купівля майна для спільного користування, участь у витратах на утримання житла та його ремонт, інші обставини, що підтверджують реальність сімейних відносин.</p>
<p><b>Критична умова, про яку згадують надто пізно:</b> особи, які проживають однією сім'єю без реєстрації шлюбу, <b>не можуть одночасно перебувати в будь-якому іншому шлюбі</b> — ні між собою, ні з третіми особами. Жінка та чоловік можуть одночасно перебувати лише в одному шлюбі (ч. 1 ст. 25 СК). Якщо хтось із партнерів формально залишається в нерозірваному шлюбі з іншою людиною, стаття 74 СК не працює, і майновий механізм, описаний нижче, недоступний.</p>
<p>І дата, від якої все це має юридичне значення: факт проживання однією сім'єю без реєстрації шлюбу набув юридичного значення з <b>1 січня 2004 року</b> — з набранням чинності Сімейним і Цивільним кодексами. Контекст — практика <a href="/practices/family-law/">сімейного права</a>.</p>`,
