        q: "Чи ділиться майно в цивільному шлюбі?",
        a: "Так. За ст. 74 СК майно, набуте за час спільного проживання однією сім'єю, належить партнерам на праві спільної сумісної власності, якщо інше не встановлено письмовим договором між ними. На таке майно поширюються положення глави 8 СК — ті самі правила, що й для майна подружжя.",
