        a: "Ні. Особи, які проживають однією сім'єю без реєстрації шлюбу, не можуть одночасно перебувати в будь-якому іншому шлюбі. Якщо хтось із партнерів формально залишається в нерозірваному шлюбі з іншою людиною, майновий механізм ст. 74 СК недоступний.",
