        h2: "Якщо чинять перешкоди: фіксація",
        html: `<p>Найважливіший практичний розділ. Без доказів перешкоджання жоден механізм не запуститься — ані виконавче провадження, ані відповідальність.</p>
<p>Що робити при кожному зірваному побаченні:</p>
<ol>
<li><b>Прибути в час і місце</b>, визначені рішенням. Навіть якщо ви впевнені, що дитину не віддадуть.</li>
<li><b>Викликати поліцію</b> і домогтися реєстрації звернення. Отримайте номер — це офіційний слід.</li>
<li><b>Зафіксувати факт</b> — відео, фото з часом, свідки.</li>
<li><b>Зберігати листування</b> — повідомлення з відмовами, аудіо розмов там, де це допустимо.</li>
<li><b>Письмово звертатися</b> до другого з батьків із фіксацією надсилання.</li>
</ol>
<p>Один зірваний візит нічого не доводить — його завжди пояснять випадковістю. <b>Систему</b> доводить лише накопичений масив однотипних фіксацій за кілька місяців.</p>
<p>Окремо: не забирайте дитину силою й не влаштовуйте сцен у присутності дитини. Це не лише шкодить їй, а й негайно обертається проти вас у суді — саме такі епізоди стають основою зустрічних вимог про обмеження спілкування.</p>`,
