        h2: "Примусове виконання рішення",
        html: `<p>Рішення суду про графік побачень — це виконавчий документ, і воно виконується через виконавчу службу так само, як рішення про стягнення коштів. Про це багато хто не знає й роками живе з невиконаним рішенням.</p>
<p>Порядок дій:</p>
<ol>
<li><b>Отримати виконавчий лист</b> у суді, який ухвалив рішення.</li>
<li><b>Подати заяву</b> про відкриття виконавчого провадження — державному або приватному виконавцю.</li>
<li><b>Виконавець виносить постанову</b> про відкриття провадження і встановлює строк для добровільного виконання.</li>
<li><b>Виконавчі дії за місцем проживання боржника</b> — виконавець прибуває у визначений графіком час.</li>
<li><b>Складання акта</b> про невиконання рішення, якщо дитину не передають.</li>
</ol>
<p>Це рішення <b>немайнового характеру</b>, і виконання має особливості: воно провадиться за участю представника органу опіки та піклування, а за потреби — залучається психолог. Присутність цих осіб не формальність: саме їхня фіксація обставин має вагу при подальшому застосуванні санкцій.</p>
<p>Важливо: виконавець не може «відібрати» дитину силою під час звичайного побачення. Його інструмент — фіксація невиконання та подальші санкції до боржника.</p>`,
