        html: `<p>За невиконання рішення немайнового характеру виконавець накладає на боржника <b>штраф</b>. За повторне невиконання після цього розмір штрафу зростає.</p>
<p>Якщо рішення й далі не виконується, виконавець вносить подання до правоохоронних органів. Умисне невиконання судового рішення є <b>кримінальним правопорушенням</b>.</p>
<p>Реалістична оцінка, яку варто мати на увазі: кримінальне провадження в таких справах рідко доходить до вироку. Його реальна цінність в іншому — це найсерйозніший важіль тиску, після якого більшість боржників починають виконувати рішення. Розраховувати на нього як на швидкий спосіб побачити дитину не варто.</p>
<p>Паралельно накопичена документація про систематичне перешкоджання стає доказовою базою для перегляду питання про місце проживання дитини — і це, як показує практика, працює переконливіше за штрафи.</p>`,
