<p>Додатково згоди одного з батьків достатньо, якщо <b>відомості про батька (матір) виключено з актового запису</b> про народження дитини, або якщо відомості про чоловіка як батька внесені до актового запису <b>за заявою матері</b>. Останній випадок стосується дітей, народжених жінкою, яка не перебувала у шлюбі, за відсутності добровільного визнання батьківства.</p>
