<p>Можливість <b>змінити по батькові</b> з'явилася з 1 січня 2021 року: тоді набрали чинності зміни до статті 295 Цивільного кодексу і статті 149 Сімейного кодексу. Правила побудовані так само, як для прізвища: той самий перелік випадків, коли достатньо згоди одного з батьків, і той самий порядок вирішення спору — <b>органом опіки та піклування або судом</b>. При вирішенні спору беруться до уваги виконання батьками своїх обов'язків стосовно дитини та інші обставини, що засвідчують відповідність зміни інтересам дитини.</p>
