        h2: "Припинення опіки та звільнення опікуна",
        html: `<p>Закон розрізняє дві різні ситуації, і це розмежування має практичне значення.</p>
<p><b>Припинення опіки, піклування</b> (ст. 250 СК) відбувається у випадках, встановлених Цивільним кодексом. Найчастіші підстави: досягнення дитиною 14 років (опіка переходить у піклування) і 18 років (піклування припиняється), усиновлення дитини, повернення дитини батькам, набуття дитиною повної цивільної дієздатності, смерть опікуна або підопічного.</p>
<p><b>Звільнення опікуна або піклувальника від обов'язків</b> (ст. 251 СК) — інше. Особа може бути звільнена у випадках, передбачених Цивільним кодексом, <b>а також тоді, коли між опікуном, піклувальником і дитиною склалися стосунки, які перешкоджають здійсненню ними опіки, піклування</b>. Остання підстава сформульована нейтрально: вона не вимагає доводити вину опікуна, достатньо показати, що стосунки склалися саме так. Нею користуються і самі опікуни, коли розуміють, що не справляються.</p>
<p>Окремо опікун може бути звільнений <b>за власною заявою</b>, і орган опіки та піклування не може безпідставно в цьому відмовити. Якщо ж опікун неналежно виконує обов'язки, зловживає правами або використовує кошти дитини не за призначенням, рішення про звільнення ухвалюється незалежно від його бажання, а за наявності ознак правопорушення — з повідомленням правоохоронних органів.</p>
<p>Якщо йдеться про ситуацію, коли батьки дитини не виконують обов'язків і постає питання про їхній статус, потрібна окрема процедура — вона описана в матеріалі про <a href="/blog/pozbavlennya-batkivskykh-prav/">позбавлення батьківських прав</a>. Питання стягнення утримання з батьків на користь дитини під опікою — у матеріалі про <a href="/blog/alimenty-na-dytynu/">аліменти на дитину</a>.</p>`,
