        h2: "Крок 3: свідоцтво про право на спадщину та реєстрація",
        html: `<p>Після спливу шестимісячного строку нотаріус видає <strong>свідоцтво про право на спадщину</strong> (стаття 1296 ЦК України). Для нерухомого майна отримання свідоцтва є обов'язковим (стаття 1297 ЦК України): без нього неможливо ані продати, ані подарувати, ані заповісти успадковану квартиру чи <a href=\"/practices/land-law/\">земельну ділянку</a>.</p>
<p>Видаючи свідоцтво на нерухомість, нотаріус одночасно реєструє право власності спадкоємця в Державному реєстрі речових прав — окремо йти до реєстратора не потрібно. Особливості успадкування квартир, будинків і землі, включно з незавершеним будівництвом і неоформленими за життя об'єктами, ми розібрали у статті <a href="/blog/spadkuvannya-nerukhomosti/">про спадкування нерухомості</a>.</p>`,
