        html: `<p>До складу спадщини входять не лише права, а й <strong>обов'язки спадкодавця</strong>, які не припинилися з його смертю (статті 1218, 1219 Цивільного кодексу України). Це кредити й позики, заборгованість за комунальні послуги, податкові борги, невиконані договірні зобов'язання, відшкодування майнової шкоди.</p>
<p>Не переходять у спадщину обов'язки, нерозривно пов'язані з особою померлого: аліменти, відшкодування шкоди, завданої каліцтвом, права та обов'язки як сторони особистих договорів (стаття 1219 ЦК України). Нараховані за життя, але не сплачені суми аліментної заборгованості — окрема історія: вони вже є грошовим боргом і можуть стягуватися зі спадщини.</p>`,
