        h2: "Право представлення: коли спадкують онуки",
        html: `<p>Онуки й правнуки не входять до жодної черги, але спадкують <strong>за правом представлення</strong> (стаття 1266 ЦК України): якщо дитина спадкодавця померла раніше за нього, її частку отримують її діти — онуки спадкодавця. Так само прабаба й прадід представляють своїх дітей (бабу/діда спадкодавця), племінники — своїх батьків (братів/сестер спадкодавця), двоюрідні брати й сестри — своїх батьків (дядька/тітку спадкодавця).</p>
<p>Приклад: у спадкодавця було двоє синів, один помер раніше, залишивши двох дітей. Спадщина ділиться навпіл: 1/2 — живому синові, а другу половину порівну ділять двоє онуків — по 1/4. Право представлення діє лише при спадкуванні за законом і не застосовується, якщо спадкоємець був живий на момент відкриття спадщини, але помер, не встигнувши прийняти її, — тоді працює інший механізм, спадкова трансмісія (стаття 1276 ЦК України).</p>`,
