        html: `<p>За спадковим договором одна сторона — <strong>набувач</strong> — зобов'язується виконувати розпорядження другої сторони — <strong>відчужувача</strong> — і в разі його смерті набуває право власності на визначене договором майно (стаття 1302 Цивільного кодексу України). Розпорядження можуть бути будь-якими законними: доглядати, сплачувати кошти, забезпечити проживання, поховати за певним звичаєм.</p>
<p>Головний юридичний ефект: майно, визначене договором, <strong>не входить до складу спадщини</strong>. Воно переходить набувачеві поза спадковими процедурами — без шестимісячних строків, без черг і без конкуренції з іншими родичами.</p>`,
