        html: `<ul>
<li><b>Досягнення 23 років</b> — беззастережна межа для підстави «продовження навчання».</li>
<li><b>Припинення навчання</b> — відрахування, академічна відпустка з працевлаштуванням, завершення навчання.</li>
<li><b>Відпадіння потреби в допомозі</b> — наприклад, дитина почала повноцінно працювати.</li>
<li><b>Істотне погіршення становища платника</b> — підстава не для припинення, а для <a href="/blog/zmenshennya-rozmiru-alimentiv/">зменшення розміру аліментів</a>.</li>
</ul>
<p>Припинення не відбувається саме собою: платнику потрібно звернутися до суду з відповідною вимогою або до виконавця з документами про відпадіння підстав. Доки цього не зроблено, нарахування тривають.</p>
<p>Адвокати практики <a href="/practices/family-law/">сімейного права LEGIUS</a> ведуть справи про стягнення аліментів на повнолітніх дітей і про припинення таких виплат.</p>`,
