        html: `<p>Конвенція про цивільно-правові аспекти міжнародного викрадення дітей 1980 року вирішує <b>одне питання</b>: чи має дитина бути негайно повернута до країни свого звичайного місця проживання.</p>
<p>Це принципово важливо розуміти. Конвенція <b>не визначає</b>, з ким із батьків житиме дитина, не встановлює графік спілкування і не вирішує спір про виховання. Вона лише відновлює становище, що існувало до незаконного переміщення, щоб спір по суті розглядав суд тієї країни, де дитина проживала.</p>
<p>Конвенція застосовується до дітей віком до 16 років. Після досягнення цього віку механізм не працює.</p>`,
