        html: `<p>Друга поширена тактика — просто не з’являтися, розраховуючи, що без відповідача справу не розглянуть.</p>
<p>Це не працює. Неявка відповідача, повідомленого належним чином, не перешкоджає розгляду справи. Суд може ухвалити рішення за наявними матеріалами, зокрема заочне рішення.</p>
<p>Умова одна, зате сувора — <b>належне повідомлення</b>. Тому ключове завдання позивача не в тому, щоб «привести» відповідача до суду, а в тому, щоб у справі були докази його виклику: рекомендовані листи, дані про вручення, відомості про розміщення оголошення.</p>
<p>Заочне рішення має особливість: відповідач може подати заяву про його перегляд протягом встановленого строку. Тому в справах, де очікується така поведінка, часто доцільніше домогтися звичайного рішення.</p>`,
