        id: "s1",
        h2: "Безробіття не звільняє від аліментів",
        html: `<p>Найпоширеніший міф серед платників: «я не працюю, отже платити нічим». Юридично це не так. Обов’язок утримувати дитину випливає з факту батьківства, а не з наявності роботи.</p>
<p>Батьки зобов’язані утримувати дитину незалежно від свого матеріального становища. Відсутність доходу може вплинути на <b>розмір</b> аліментів, але не скасовує сам обов’язок і не зупиняє нарахування.</p>
<p>Практичний наслідок: у непрацюючого платника борг накопичується так само, як у працюючого. Різниця лише в тому, що стягувати його доводиться не із зарплати, а іншими способами.</p>`,
