        h2: "Тверда сума замість частки",
        html: `<p>Стягувати частку від заробітку з людини без заробітку безглуздо — чверть від нуля дорівнює нулю. Тому в таких справах аліменти присуджують <b>у твердій грошовій сумі</b>.</p>
<p>Діє гарантована нижня межа: розмір аліментів на одну дитину не може бути меншим за половину прожиткового мінімуму для дитини відповідного віку. Закон окремо називає й рекомендований орієнтир — повний прожитковий мінімум.</p>
<p>Суд враховує стан здоров’я та матеріальне становище дитини й платника, наявність інших дітей на утриманні та інші істотні обставини. Але «не маю доходу» саме по собі підставою для мінімального розміру не є — суд оцінює <b>спроможність</b>, а не лише офіційну довідку.</p>
<p>Механізм вибору способу стягнення розібраний у матеріалі про <a href="/blog/alimenty-tverda-groshova-suma/">аліменти у твердій грошовій сумі</a>.</p>`,
