        html: `<p>Це ключове, чого не знає більшість платників, і що варто знати стягувачам.</p>
<p>Якщо особа у період утворення заборгованості не працювала, розмір боргу визначається виходячи із <b>середньої заробітної плати працівника відповідної кваліфікації або середньої заробітної плати в даній місцевості</b>.</p>
<p>Практичний наслідок парадоксальний: борг непрацюючого нерідко виявляється <b>більшим</b>, ніж у того, хто працює за мінімальною ставкою. Розрахунок робиться не від нуля, а від середнього показника.</p>
<p>Розрахунок заборгованості здійснює виконавець за заявою стягувача. Отримати цей розрахунок — перший практичний крок у будь-якій справі про борг: без нього немає ані підстави для пені, ані підстави для обмежень.</p>`,
