        h2: "Судово-психіатрична експертиза",
        html: `<p>Це центральний елемент справи. Суд <b>зобов’язаний</b> призначити судово-психіатричну експертизу за наявності достатніх даних про психічний розлад — без висновку експертів визнати особу недієздатною неможливо.</p>
<p>Експертиза відповідає на два питання: чи страждає особа на психічний розлад і чи здатна вона усвідомлювати значення своїх дій та керувати ними.</p>
<p>Форми проведення:</p>
<ul>
<li><b>амбулаторна</b> — найпоширеніша, особа приходить або її привозять на огляд;</li>
<li><b>стаціонарна</b> — якщо потрібне тривале спостереження;</li>
<li><b>за медичними документами</b> — коли особа фізично не може бути оглянута.</li>
</ul>
<p>Якщо особа ухиляється від проходження експертизи, суд може постановити рішення про її примусове направлення — за участю відповідних органів. Це виняткова міра, але вона існує саме для таких ситуацій.</p>
<p>Строк експертизи — головна причина тривалості справи. Реалістично закладайте кілька місяців на весь процес, і більша частина цього часу піде саме на експертизу.</p>`,
